function descargar(url, destino, intentos) {
  return new Promise((resolve, reject) => {
    const proto = url.startsWith('https') ? https : http;
    proto.get(url, { headers: { 'User-Agent': 'Mozilla/5.0' } }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        // Seguir redireccion
        descargar(res.headers.location, destino, intentos).then(resolve).catch(reject);
        return;
      }
      if (res.statusCode !== 200) {
        reject(new Error(`HTTP ${res.statusCode} descargando audio`)); return;
      }
      const total = parseInt(res.headers['content-length'] || '0');
      let descargado = 0;
      const archivo = fs.createWriteStream(destino);
      res.on('data', chunk => {
        descargado += chunk.length;
        if (total > 0 && descargado % (1024*1024*50) < chunk.length) {
          console.log(`  ${Math.round(descargado/1024/1024)}MB / ${Math.round(total/1024/1024)}MB`);
        }
      });
      res.pipe(archivo);
      archivo.on('finish', () => { archivo.close(); resolve(); });
      archivo.on('error', (e) => { fs.unlink(destino, ()=>{}); reject(e); });
    }).on('error', (e) => { fs.unlink(destino, ()=>{}); reject(e); });
  });
}

