      console.log(`Body (${body.length} bytes): ${body.slice(0, 500)}`);
      if (res.statusCode >= 200 && res.statusCode < 300) {
        try { resolve(JSON.parse(body)); }
        catch(e) { reject(new Error(`HTTP ${res.statusCode} pero body no es JSON: ${body.slice(0,200)}`)); }
      } else if (res.statusCode === 308) {
        reject(new Error(`Upload incompleto (308). Probablemente la URL expiro o se interrumpio. Reintenta desde Iniciar Upload.`));
      } else {
        reject(new Error(`HTTP ${res.statusCode}: ${body.slice(0,300)}`));
      }
    });
  });
  req.on('error', (e) => reject(new Error(`Error de red: ${e.message}`)));
  fileStream.on('error', (e) => reject(new Error(`Error leyendo archivo: ${e.message}`)));
  fileStream.pipe(req);
});

if (!result.id) throw new Error('YouTube no devolvio video ID: ' + JSON.stringify(result));

